// Group Anagrams - Group words that are anagrams of each other
var table = AnimatedHashTable<String, String>()
let words = ["eat", "tea", "tan", "ate", "nat", "bat"]

func sortChars(_ word: String) -> String {
    return String(word.sorted())
}

for word in words {
    let key = sortChars(word)
    if let existing = table.get(key) {
        table.put(key, existing + "," + word)
    } else {
        table.put(key, word)
    }
}
